def SliceCriterion (𝕜 E : Type*) [RCLike 𝕜] [NormedAddCommGroup E] [NormedSpace 𝕜 E] : Prop :=
  ∀ h : E, ‖h‖ = 1 → ∀ φ : E →L[𝕜] 𝕜, ‖φ‖ = 1 → ∀ ε : ℝ, 0 < ε →
    ∃ x : E, ‖x‖ ≤ 1 ∧ 1 - ε < RCLike.re (φ x) ∧ 2 - ε < ‖h + x‖

